// Everything the scene needs before frame 0 can be drawn: web fonts for
// canvas textures and the HUD, typeface JSON for extruded 3D text, and any
// JSON data. The composition mounts its ThreeCanvas only once this is ready,
// so no frame is ever drawn with a fallback font.
import { useEffect, useState } from "react";
import { staticFile, useDelayRender } from "remotion";
import { Font, FontLoader } from "three/examples/jsm/loaders/FontLoader.js";
import { loadFont as loadMono } from "@remotion/google-fonts/JetBrainsMono";
import { loadFont as loadSans } from "@remotion/google-fonts/Inter";

const mono = loadMono("normal", { weights: ["400", "500", "700"], subsets: ["latin"] });
const sans = loadSans("normal", { weights: ["500", "700", "800"], subsets: ["latin"] });
export const MONO = `${mono.fontFamily}, monospace`;
export const SANS = `${sans.fontFamily}, sans-serif`;

const typefaces = new Map<string, Font>();
const json = new Map<string, unknown>();

export const getTypeface = (path: string) => {
  const f = typefaces.get(path);
  if (!f) throw new Error(`Typeface ${path} was not listed in useAssets()`);
  return f;
};
export const getJson = <T,>(path: string) => {
  if (!json.has(path)) throw new Error(`JSON ${path} was not listed in useAssets()`);
  return json.get(path) as T;
};

const loadTypeface = async (path: string) => {
  if (typefaces.has(path)) return;
  const r = await fetch(staticFile(path));
  typefaces.set(path, new FontLoader().parse((await r.json()) as never));
};
const loadJson = async (path: string) => {
  if (json.has(path)) return;
  const r = await fetch(staticFile(path));
  json.set(path, await r.json());
};

/** Hold the render until fonts, typefaces and data are in memory. */
export const useAssets = (opts: { typefaces?: string[]; json?: string[] }) => {
  const { delayRender, continueRender, cancelRender } = useDelayRender();
  const [handle] = useState(() => delayRender("Loading fonts, typefaces and data"));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    Promise.all([
      mono.waitUntilDone(),
      sans.waitUntilDone(),
      ...(opts.typefaces ?? []).map(loadTypeface),
      ...(opts.json ?? []).map(loadJson),
    ])
      .then(() => document.fonts.ready)
      .then(() => setReady(true))
      .catch((e) => cancelRender(e));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // Release only after the commit that mounts the canvas, so its own hold is already in place.
  useEffect(() => {
    if (ready) continueRender(handle);
  }, [ready, handle, continueRender]);
  return ready;
};

// A camera you direct like a DP: lenses in millimetres, shots that move from
// A to B with an ease that lands on the beat, and a hold that never locks.
import { useThree } from "@react-three/fiber";
import { useLayoutEffect } from "react";
import { PerspectiveCamera, Vector3 } from "three";
import { fbm, land, mix, mix3, clamp01, type Ease, type V3 } from "./motion";

/** Vertical field of view for a full-frame (36x24 mm) lens at this focal length. */
export const fovFor = (mm: number, aspect = 16 / 9) => {
  // Full frame is 36 mm wide; take the sensor height from the frame's aspect.
  const sensorH = 36 / aspect;
  return (2 * Math.atan(sensorH / 2 / mm) * 180) / Math.PI;
};

export type CamPose = { pos: V3; target: V3; mm: number; roll?: number };
export type Shot = {
  from: number;
  to: number;
  a: CamPose;
  /** Omit for a held shot (still drifts). */
  b?: CamPose;
  ease?: Ease;
  /** Handheld amount in degrees of wander. 0.15-0.4 reads as a person holding still. */
  drift?: number;
  /** Shutter: 0..1 of how much this move should smear (read by MotionBlur overlays). */
  name?: string;
};

export type CamState = CamPose & { shot: number; t: number; speed: number; drift: number };

const pose = (s: Shot, t: number): CamPose => {
  if (!s.b) return s.a;
  return {
    pos: mix3(s.a.pos, s.b.pos, t),
    target: mix3(s.a.target, s.b.target, t),
    mm: mix(s.a.mm, s.b.mm, t),
    roll: mix(s.a.roll ?? 0, s.b.roll ?? 0, t),
  };
};

/** Where the camera is on this frame. Shots are cut back to back; a frame past the last shot holds it. */
export const camAt = (frame: number, shots: Shot[]): CamState => {
  let i = shots.findIndex((s) => frame >= s.from && frame < s.to);
  if (i < 0) i = frame < shots[0].from ? 0 : shots.length - 1;
  const s = shots[i];
  const raw = clamp01((frame - s.from) / Math.max(1, s.to - s.from));
  const e = s.ease ?? land;
  const t = e(raw);
  const p = pose(s, t);
  const p2 = pose(s, e(clamp01(raw + 1 / Math.max(1, s.to - s.from))));
  const speed = Math.hypot(p2.pos[0] - p.pos[0], p2.pos[1] - p.pos[1], p2.pos[2] - p.pos[2]);
  return { ...p, shot: i, t: raw, speed, drift: s.drift ?? 0.25 };
};

const tmp = new Vector3();

/** Drives the default R3F camera from a CamState. Put it inside the ThreeCanvas. */
export const Camera: React.FC<{ state: CamState; frame: number; fps: number; near?: number; far?: number }> = ({
  state,
  frame,
  fps,
  near = 0.01,
  far = 60,
}) => {
  const camera = useThree((s) => s.camera) as PerspectiveCamera;
  const size = useThree((s) => s.size);
  // Runs during the R3F commit, before @remotion/three advances the renderer.
  useLayoutEffect(() => {
    const aspect = size.width / size.height;
    camera.fov = fovFor(state.mm, aspect);
    camera.aspect = aspect;
    camera.near = near;
    camera.far = far;
    camera.position.set(...state.pos);
    camera.up.set(0, 1, 0);
    camera.lookAt(tmp.set(...state.target));
    const t = frame / fps;
    const d = (state.drift * Math.PI) / 180;
    camera.rotateY(fbm(t * 0.45, 1) * d);
    camera.rotateX(fbm(t * 0.38, 2) * d * 0.8);

// Live 2D textures for screens, paper and code pages. The canvas is redrawn
// whenever `key` changes (usually the frame or the typed character count),
// during render, so the texture is current before the frame is drawn.
import { useMemo } from "react";
import { CanvasTexture, LinearFilter, SRGBColorSpace } from "three";

export const useCanvasTexture = (
  w: number,
  h: number,
  draw: (g: CanvasRenderingContext2D, w: number, h: number) => void,
  key: unknown,
) => {
  const { canvas, tex } = useMemo(() => {
    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const tex = new CanvasTexture(canvas);
    tex.colorSpace = SRGBColorSpace;
    tex.anisotropy = 8;
    tex.minFilter = LinearFilter;
    tex.generateMipmaps = false;
    return { canvas, tex };
  }, [w, h]);
  useMemo(() => {
    const g = canvas.getContext("2d")!;
    g.clearRect(0, 0, w, h);
    draw(g, w, h);
    tex.needsUpdate = true;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [canvas, tex, key]);
  return tex;
};

/** Wrap text to a width on a 2D canvas. */
export const wrap = (g: CanvasRenderingContext2D, text: string, maxW: number) => {
  const words = text.split(" ");
  const lines: string[] = [];
  let cur = "";
  for (const w of words) {
    const t = cur ? `${cur} ${w}` : w;
    if (g.measureText(t).width > maxW && cur) {
      lines.push(cur);
      cur = w;
    } else cur = t;
  }
  if (cur) lines.push(cur);
  return lines;
};

// Set pieces that show the four pillars on screen: a motion path with
// keyframe diamonds and a flying object (MOTION), audio bars standing on the
// set (SOUND), and a fanned stack of the film's real source code (the code
// count shot).
import { useMemo } from "react";
import {
  Object3D,
  BoxGeometry,
  BufferGeometry,
  CatmullRomCurve3,
  Float32BufferAttribute,
  OctahedronGeometry,
  PlaneGeometry,
  Vector3,
} from "three";
import { Solid, usePass, INK } from "./pass";
import { useCanvasTexture } from "./canvasTex";
import { MONO } from "./assets";
import { RED } from "./film";
import type { V3 } from "./motion";

const aimer = new Object3D();
const aim = (from: Vector3, to: Vector3) => {
  aimer.position.copy(from);
  aimer.lookAt(to);
  return aimer.quaternion.clone();
};

/** A folded paper plane, nose along +Z. */
export const usePaperPlaneGeometry = () =>
  useMemo(() => {
    const g = new BufferGeometry();
    // nose, left wing tip, keel, right wing tip, tail points
    const v = [
      // left wing
      0, 0, 0.09, -0.045, 0.004, -0.05, 0, 0, -0.05,
      // right wing
      0, 0, 0.09, 0, 0, -0.05, 0.045, 0.004, -0.05,
      // keel
      0, 0, 0.09, 0, -0.018, -0.05, 0, 0, -0.05,
    ];
    g.setAttribute("position", new Float32BufferAttribute(v, 3));
    g.computeVertexNormals();
    return g;
  }, []);

/** A curve through points, drawn with keyframe diamonds, plus an object that travels it. */
export const MotionPath: React.FC<{
  points: V3[];
  /** 0..1 progress of the traveller along the path. */
  t: number;
  /** How much of the path is drawn (0..1). */
  drawn?: number;
  children?: React.ReactNode;
}> = ({ points, t, drawn = 1, children }) => {
  const pass = usePass();
  const curve = useMemo(() => new CatmullRomCurve3(points.map((p) => new Vector3(...p)), false, "centripetal"), [points]);
  const line = useMemo(() => {
    const n = 160;
    const pts = curve.getSpacedPoints(n).slice(0, Math.max(2, Math.floor(n * drawn) + 1));
    return new BufferGeometry().setFromPoints(pts);
  }, [curve, drawn]);
  const diamond = useMemo(() => new OctahedronGeometry(0.012, 0), []);
  const p = curve.getPointAt(Math.min(0.999, Math.max(0, t)));
  const ahead = curve.getPointAt(Math.min(1, Math.max(0, t) + 0.01));
  const color = pass === "wire" ? INK : "#ffd9a8";
  return (
    <group>
      <line>
        <primitive object={line} attach="geometry" />
        <lineBasicMaterial color={color} toneMapped={false} transparent opacity={0.9} />
      </line>
      {points.map((q, i) =>
        i / (points.length - 1) <= drawn + 1e-3 ? (
          <group key={i} position={q} scale={[1, 1.5, 1]}>
            <Solid geometry={diamond} color="#ffd9a8" emissive="#ffb070" emissiveIntensity={2} castShadow={false} edgeAngle={1} />
          </group>
        ) : null,
      )}
      <group position={p} quaternion={aim(p, ahead)}>

// 2D layers over the 3D: film grain, gate weave, shutter smear on whips, and
// the HUD language of "this is code" (red mono section tags, a frame counter,
// a pass label, code annotations pinned to objects).
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { PerspectiveCamera, Vector3 } from "three";
import { fbm, type V3 } from "./motion";
import { fovFor, type CamState } from "./camera";
import { MONO } from "./assets";

export const RED = "#e5483a";

/** 35 mm grain. Deterministic: the seed is the frame. */
export const Grain: React.FC<{ amount?: number }> = ({ amount = 0.1 }) => {
  const frame = useCurrentFrame();
  return (
    <AbsoluteFill style={{ mixBlendMode: "overlay", opacity: amount, pointerEvents: "none" }}>
      <svg width="100%" height="100%">
        <filter id={`grain-${frame}`}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={frame % 997} stitchTiles="stitch" />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#grain-${frame})`} />
      </svg>
    </AbsoluteFill>
  );
};

/** Projector gate weave: the whole frame breathes by a pixel or two. */
export const Weave: React.FC<{ children: React.ReactNode; px?: number }> = ({ children, px = 1.2 }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const t = frame / fps;
  return (
    <AbsoluteFill style={{ transform: `translate(${fbm(t * 1.7, 21) * px}px, ${fbm(t * 1.3, 22) * px}px)` }}>
      {children}
    </AbsoluteFill>
  );
};

/**
 * Shutter smear for whip pans: a directional blur scaled by how fast the
 * camera moves this frame. `speed` is world units per frame from camAt().
 */
export const Shutter: React.FC<{ speed: number; angle?: number; gain?: number; children: React.ReactNode; id: string }> = ({
  speed,
  angle = 0,
  gain = 900,
  children,
  id,
}) => {
  const px = Math.min(60, speed * gain);
  if (px < 1.5) return <AbsoluteFill>{children}</AbsoluteFill>;
  return (
    <AbsoluteFill>
      <svg width="0" height="0" style={{ position: "absolute" }}>
        <filter id={id} x="-5%" y="-5%" width="110%" height="110%">
          <feGaussianBlur stdDeviation={`${px} ${px * 0.12}`} />
        </filter>
      </svg>
      <AbsoluteFill style={{ filter: `url(#${id})`, transform: `rotate(${angle}deg)` }}>
        <AbsoluteFill style={{ transform: `rotate(${-angle}deg)` }}>{children}</AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

/** Red mono section tag, typed on with a block cursor. */
export const Tag: React.FC<{ text: string; start: number; x: number; y: number; size?: number; cps?: number; end?: number; color?: string }> = ({
  text,
  start,
  x,
  y,
  size = 64,
  cps = 22,
  end,
  color = RED,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  if (frame < start || (end !== undefined && frame >= end)) return null;

// Light like a cinematographer: one motivated key (the sun through blinds),
// a warm bounce off the surfaces it hits, haze in the beam and dust that only
// glows where the beam is. The blinds are real geometry: the stripes are
// real shadows, so they wrap over every object.
import { useLayoutEffect, useMemo, useRef } from "react";
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  CanvasTexture,
  DirectionalLight,
  Matrix4,
  Object3D,
  Vector3,
} from "three";
import { usePass } from "./pass";
import { fbm, rand, type V3 } from "./motion";

export type Blinds = {
  /** Window centre (in the wall plane). */
  center: V3;
  /** Window width and height in metres. */
  w: number;
  h: number;
  /** Outward normal of the wall the window is in (pointing out of the room). */
  normal: V3;
  /** Slat pitch and how open they are (0 closed, 1 fully open). */
  pitch?: number;
  open?: number;
  /** Slat tilt in degrees: tilts the stripes on the floor. */
  tilt?: number;
};

const v = (a: V3) => new Vector3(...a);

/** Invisible slats that only exist for the shadow map, so the sun is striped. */
export const BlindsGobo: React.FC<{ blinds: Blinds; visible?: boolean }> = ({ blinds, visible }) => {
  const { center, w, h, normal, pitch = 0.05, open = 0.45, tilt = 0 } = blinds;
  const n = Math.floor(h / pitch);
  const slatH = pitch * (1 - open);
  const yaw = Math.atan2(normal[0], normal[2]);
  return (
    <group position={center} rotation={[0, yaw, 0]}>
      {Array.from({ length: n }, (_, i) => (
        <mesh
          key={i}
          position={[0, -h / 2 + (i + 0.5) * pitch, 0]}
          rotation={[((tilt + 35) * Math.PI) / 180, 0, 0]}
          castShadow
        >
          <boxGeometry args={[w, slatH, 0.004]} />
          {visible ? (
            <meshStandardMaterial color="#e9e2d4" roughness={0.5} />
          ) : (
            <meshBasicMaterial colorWrite={false} depthWrite={false} />
          )}
        </mesh>
      ))}
    </group>
  );
};

/**
 * The key light. A directional "sun" coming through the window, with a tight
 * shadow frustum around the set so the stripes stay crisp.
 */
export const Sun: React.FC<{
  /** Direction the light travels (from the sun into the room). */
  dir: V3;
  /** Point the shadow frustum is centred on. */
  focus: V3;
  intensity?: number;
  color?: string;
  /** Half-size of the shadow frustum in metres. Smaller is sharper. */
  span?: number;
  mapSize?: number;
  /** Soft flicker of passing air / cloud, 0..1. */
  flicker?: number;
  frame: number;
  fps: number;

// Motion math for code-driven cinematography. Everything is a pure function
// of the frame number: no clocks, no randomness, no useFrame.
import { Easing } from "remotion";

export type V3 = [number, number, number];
export type Ease = (t: number) => number;

/** Land on the beat: fast start, long soft settle. The default for every move. */
export const land: Ease = Easing.bezier(0.2, 0.8, 0.2, 1);
/** Whip: hold, snap through the middle, settle. Pair with motion blur. */
export const whip: Ease = Easing.bezier(0.7, 0, 0.2, 1);
/** Slow drift in and out, for long holds that must still breathe. */
export const glide: Ease = Easing.bezier(0.45, 0, 0.55, 1);
export const linear: Ease = (t) => t;

export const clamp01 = (t: number) => Math.min(1, Math.max(0, t));
export const mix = (a: number, b: number, t: number) => a + (b - a) * t;
export const mix3 = (a: V3, b: V3, t: number): V3 => [mix(a[0], b[0], t), mix(a[1], b[1], t), mix(a[2], b[2], t)];

/** Progress through [from, to] in frames, eased. */
export const prog = (frame: number, from: number, to: number, ease: Ease = land) =>
  ease(clamp01((frame - from) / Math.max(1, to - from)));

// Deterministic value noise. Same frame, same value, on every render worker.
const hash = (n: number) => {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
};
export const noise1 = (t: number, seed = 0) => {
  const i = Math.floor(t);
  const f = t - i;
  const u = f * f * (3 - 2 * f);
  return mix(hash(i + seed * 17.13), hash(i + 1 + seed * 17.13), u) * 2 - 1;
};
/** Layered noise in [-1, 1]: handheld breathing, flicker, gate weave. */
export const fbm = (t: number, seed = 0) =>
  noise1(t, seed) * 0.62 + noise1(t * 2.13, seed + 3.1) * 0.27 + noise1(t * 4.37, seed + 7.7) * 0.11;
/** Stable pseudo-random in [0, 1) for index i. */
export const rand = (i: number, seed = 0) => hash(i * 1.618 + seed * 9.73);

/**
 * Damped spring that overshoots a little (1-2 % by default) and settles.
 * Analytic, so any frame can be rendered alone.
 */
export const springy = (frame: number, start: number, dur = 18, overshoot = 0.018) => {
  const t = (frame - start) / dur;
  if (t <= 0) return 0;
  if (t >= 3) return 1;
  // underdamped oscillator tuned so the first peak is 1 + overshoot
  const zeta = Math.sqrt(Math.log(overshoot) ** 2 / (Math.PI ** 2 + Math.log(overshoot) ** 2));
  const wn = 4.2;
  const wd = wn * Math.sqrt(1 - zeta * zeta);
  const x = t * 1.0;
  return 1 - Math.exp(-zeta * wn * x) * (Math.cos(wd * x) + (zeta / Math.sqrt(1 - zeta * zeta)) * Math.sin(wd * x));
};

/** Count up like a ticker, landing exactly on `to`. */
export const ticker = (frame: number, from: number, to: number, a: number, b: number, ease: Ease = land) =>
  Math.round(mix(a, b, prog(frame, from, to, ease)));

/** Typewriter: how many characters of `text` are visible. `cps` is characters per second. */
export const typed = (frame: number, start: number, text: string, cps = 28, fps = 30) =>
  text.slice(0, Math.max(0, Math.floor(((frame - start) / fps) * cps)));

// Render passes. The same world renders as the finished "beauty" image, as a
// line-art "wire" pass on paper, or as the flat untextured look you get from a
// plain prompt ("flat"). Cutting between passes is the signature move: it
// shows the audience that the shot is made of code.
import { createContext, useContext, useMemo } from "react";
import { useThree } from "@react-three/fiber";
import {
  BackSide,
  BufferGeometry,
  Color,
  DoubleSide,
  EdgesGeometry,
  FrontSide,
  ShaderMaterial,
  type Side,
  type Texture,
} from "three";

export type PassName = "beauty" | "wire" | "flat";
export const PassContext = createContext<PassName>("beauty");
export const usePass = () => useContext(PassContext);

export const PAPER = "#ecebe6";
export const INK = "#2b2a28";

// Silhouette lines for the wire pass: an inverted hull pushed out along the
// normals by a constant number of pixels, so smooth (rounded) objects get an
// outline even where they have no crease edges.
const hullMaterial = (() => {
  let m: ShaderMaterial | null = null;
  return () => {
    if (m) return m;
    m = new ShaderMaterial({
      uniforms: { uPx: { value: 1.6 }, uRes: { value: [1920, 1080] }, uColor: { value: new Color(INK) } },
      vertexShader: `
        uniform float uPx; uniform vec2 uRes;
        void main() {
          vec4 clip = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
          vec3 n = normalize(normalMatrix * normal);
          vec2 d = (projectionMatrix * vec4(n, 0.0)).xy;
          float l = length(d);
          if (l > 1e-5) clip.xy += d / l * uPx * 2.0 / uRes * clip.w;
          gl_Position = clip;
        }`,
      fragmentShader: `uniform vec3 uColor; void main() { gl_FragColor = vec4(uColor, 1.0); }`,
      side: BackSide,
    });
    return m;
  };
})();

export const useHull = () => {
  const size = useThree((s) => s.size);
  const m = hullMaterial();
  m.uniforms.uRes.value = [size.width, size.height];
  m.uniforms.uPx.value = Math.max(1, size.height / 700);
  return m;
};

export type SolidProps = {
  geometry: BufferGeometry;
  color?: string;
  /** Colour in the flat pass: default-prompt colours are louder and cleaner. */
  flat?: string;
  rough?: number;
  metal?: number;
  emissive?: string;
  emissiveIntensity?: number;
  map?: Texture | null;
  emissiveMap?: Texture | null;
  roughMap?: Texture | null;
  /** Keep the texture visible in the wire pass (paper text, screens). */
  mapInWire?: boolean;
  edgeAngle?: number;
  castShadow?: boolean;
  receiveShadow?: boolean;
  transparent?: boolean;
  opacity?: number;
  side?: "front" | "double";
  /** Hide the solid in the wire pass but keep its lines. */

// The lens and the film stock: ACES tone mapping, physical depth of field
// focused on a world point, bloom for halation, a touch of chromatic
// aberration and vignette. Grain and gate weave are 2D (film.tsx) so they stay
// deterministic per frame.
import {
  Bloom,
  BrightnessContrast,
  ChromaticAberration,
  DepthOfField,
  EffectComposer,
  HueSaturation,
  ToneMapping,
  Vignette,
} from "@react-three/postprocessing";
import { BlendFunction, ToneMappingMode } from "postprocessing";
import { useLayoutEffect, useMemo } from "react";
import { useDelayRender } from "remotion";
import { useThree } from "@react-three/fiber";
import { Vector2 } from "three";
import { usePass } from "./pass";
import type { V3 } from "./motion";

export const Look: React.FC<{
  /** World point in focus. Omit for no depth of field. */
  focus?: V3;
  /** Size of the bokeh. 2-5 reads as a fast prime on a small set. */
  bokeh?: number;
  /** Depth in metres that stays sharp around the focus point. */
  focusRange?: number;
  bloom?: number;
  threshold?: number;
  aberration?: number;
  vignette?: number;
  saturation?: number;
  contrast?: number;
}> = ({
  focus,
  bokeh = 3,
  focusRange = 0.25,
  bloom = 0.9,
  threshold = 0.72,
